INSERT IGNORE INTO plant_molecules (plant_id, molecule_id, percentage_typical, source, role, created_at, updated_at)
SELECT p.id, 1710031, 0.002, 'Prenylated sulfur compounds in hops — Lafontaine et al. 2021', 'trace', NOW(), NOW()
FROM plants p WHERE p.latin_name LIKE 'Humulus%';
SELECT COUNT(*) as humulus_links FROM plant_molecules WHERE plant_id IN (SELECT id FROM plants WHERE latin_name LIKE 'Humulus%');

